<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head'],true)){http_response_code(403);exit('Access denied.');}if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired. Refresh the page and try again.');}$id=filter_var($_POST['session_id']??null,FILTER_VALIDATE_INT);$next=(string)($_POST['status']??'');if(!$id||!in_array($next,['Open','Closed'],true)){$_SESSION['error']='Choose a valid examination session action.';header('Location: ../?page=exams');exit;}$pdo=db();try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT id,status,opens_on,entry_deadline FROM exam_sessions WHERE id=:id FOR UPDATE');$q->execute(['id'=>$id]);$session=$q->fetch();if(!$session)throw new DomainException('Examination session not found.');if($session['status']===$next)throw new DomainException('The session already has that status.');if($next==='Open'&&($session['status']==='Closed'||date('Y-m-d')<$session['opens_on']||date('Y-m-d')>$session['entry_deadline']))throw new DomainException('Open the session only during its configured entry window. Closed sessions cannot be reopened.');$q=$pdo->prepare("UPDATE exam_sessions SET status=:status WHERE id=:id");$q->execute(['status'=>$next,'id'=>$id]);audit_log('exams.session_status_changed','exam_sessions',$id,['from'=>$session['status'],'to'=>$next]);$pdo->commit();$_SESSION['notice']='Examination session is now '.$next.'.';}catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']=$e->getMessage();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Exam session status update failed: '.$e->getMessage());$_SESSION['error']='Could not update the examination session.';}header('Location: ../?page=exams');exit;
